def extract_key_values(document_input: DocumentInput) -> ExtractionResult:
    textract_client = get_textract_client()
    response = textract_client.analyze_document(
        Document={
            'S3Object': {
                'Bucket': document_input.s3_bucket,
                'Name': document_input.s3_key
            }
        },
        FeatureTypes=['FORMS']
    )

    key_values = []
    key_map = {}
    value_map = {}
    block_map = {block['Id']: block for block in response['Blocks']}

    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'KEY' in block['EntityTypes']:
                key_map[block['Id']] = block
            else:
                value_map[block['Id']] = block

    for block_id, key_block in key_map.items():
        value_block = None
        for relationship in key_block.get('Relationships', []):
            if relationship['Type'] == 'VALUE':
                for value_id in relationship['Ids']:
                    if value_id in value_map:
                        value_block = value_map[value_id]
                        break
            if value_block:
                break

        key_text = next((block_map[child_id]['Text'] for relationship in key_block.get('Relationships', []) if relationship['Type'] == 'CHILD' for child_id in relationship['Ids'] if block_map[child_id]['BlockType'] == 'WORD'), '')
        value_text = next((block_map[child_id]['Text'] for relationship in value_block.get('Relationships', []) if relationship['Type'] == 'CHILD' for child_id in relationship['Ids'] if block_map[child_id]['BlockType'] == 'WORD'), '') if value_block else ''

        key_values.append({"key": key_text, "value": value_text})

    return ExtractionResult(key_values=key_values, raw_response=response)

